#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=6

# The org settings change only in Windows Sandbox (ADR-0012).
if [[ ! -d /c/code/v1be-infra/sandbox ]]; then
  warn "Stopping: this isn't Windows Sandbox. Open v1be-admin.wsb and run it there."
  exit 1
fi

ORG=v1be-coding
EXPECTED_PERMISSIONS="actions=read,checks=read,contents=write,issues=write,metadata=read,pull_requests=write,statuses=read"

banner "GitHub: the agent's App"

stage "Before you start"
say "This creates the GitHub App that replaces v1be-bot, then installs it."
say "It can open PRs and read CI, but can't change workflows or settings."
warn "Your password manager must be open in this Sandbox, because the clipboard"
warn "isn't shared and the key is too long to type."
if ! confirm "Is your password manager open in the Sandbox?"; then
  warn "Stopping. Open it, or tell Claude if you can't, then run this again."
  exit 1
fi
step "Create an entry named v1be-agent. It'll hold the IDs and the private key."

stage "Sign in to GitHub"
step "Sign in with your own GitHub account, the org owner."
note "This login stays in the Sandbox."
gh auth login --hostname github.com --git-protocol https --web --scopes admin:org,repo
ORG_ROLE="$(gh api "user/memberships/orgs/$ORG" --jq .role 2>/dev/null | tr -d '\r' || true)"
if [[ "$ORG_ROLE" != "admin" ]]; then
  warn "Stopping: this GitHub login isn't a $ORG owner."
  exit 1
fi
say "PASS: signed in as a $ORG owner"
pause

stage "Create the App"
open_url "https://github.com/organizations/$ORG/settings/apps/new?name=v1be-agent&description=The+coding+agent+for+V1be+Coding.&url=https%3A%2F%2Fgithub.com%2F$ORG&public=false&webhook_active=false&contents=write&pull_requests=write&issues=write&actions=read&checks=read&statuses=read"
say "The form opens with everything filled in. Check it before creating:"
step "Name: v1be-agent. If it's taken, use v1be-coding-agent."
step "Webhook: Active is off."
step "Repository permissions: Contents, Issues and Pull requests are Read and write."
step "Actions, Checks and Commit statuses are Read-only."
step "Only on this account is selected."
warn "If Workflows or Administration shows any access, stop and tell Claude."
step "Choose Create GitHub App."
pause "Press Enter when it's created."
say "The App's page is open. The App ID is near the top."
APP_ID=""; APP_SLUG=""
ask APP_ID "App ID:" || true
say "The slug is the last part of the page's address, after /apps/."
ask APP_SLUG "Slug:" || true
APP_ID="${APP_ID//[[:space:]]/}"; APP_SLUG="${APP_SLUG//[[:space:]]/}"
if [[ ! "$APP_ID" =~ ^[0-9]+$ || ! "$APP_SLUG" =~ ^[a-z0-9-]+$ ]]; then
  warn "Stopping: check the App ID and slug, and tell Claude if they look right."
  exit 1
fi

stage "Install it on the four repos"
open_url "https://github.com/apps/$APP_SLUG/installations/new"
step "Choose $ORG."
step "Choose Only select repositories, then pick all four:"
step "  .github, episode-template, series and v1be-infra."
step "Check the permissions listed, then choose Install."
pause "Press Enter when it's installed."

stage "Check the App"
INSTALLED="$(gh api "orgs/$ORG/installations" --jq ".installations[] | select(.app_slug == \"$APP_SLUG\")" 2>/dev/null | tr -d '\r' || true)"
if [[ -z "$INSTALLED" ]]; then
  warn "FAIL: $APP_SLUG isn't installed on $ORG."
  exit 1
fi
INSTALLATION_ID="$(gh api "orgs/$ORG/installations" --jq ".installations[] | select(.app_slug == \"$APP_SLUG\") | .id" | tr -d '\r')"
SELECTION="$(gh api "orgs/$ORG/installations" --jq ".installations[] | select(.app_slug == \"$APP_SLUG\") | .repository_selection" | tr -d '\r')"
PERMISSIONS="$(gh api "orgs/$ORG/installations" --jq ".installations[] | select(.app_slug == \"$APP_SLUG\") | .permissions | to_entries | map(\"\(.key)=\(.value)\") | sort | join(\",\")" | tr -d '\r')"
if [[ "$SELECTION" != "selected" ]]; then
  warn "FAIL: it can reach all repos. Change it to Only select repositories."
  exit 1
fi
if [[ "$PERMISSIONS" != "$EXPECTED_PERMISSIONS" ]]; then
  warn "FAIL: its permissions are wrong:"
  note "$PERMISSIONS"
  warn "Tell Claude this list. It holds no secrets."
  exit 1
fi
say "PASS: selected repos only"
say "PASS: exactly the expected permissions"
say "Save these in the v1be-agent entry. They aren't secret, but keep them private:"
step "App ID: $APP_ID"
step "Installation ID: $INSTALLATION_ID"
step "Slug: $APP_SLUG"
pause "Press Enter when they're saved."

stage "Save the private key"
open_url "https://github.com/organizations/$ORG/settings/apps/$APP_SLUG"
step "Under Private keys, choose Generate a private key. It downloads a .pem file."
step "The Sandbox may have no Notepad, so copy it from a new PowerShell window:"
say '  Get-Content (Get-ChildItem "$HOME\Downloads\*.pem" | Sort-Object LastWriteTime | Select-Object -Last 1).FullName -Raw | Set-Clipboard'
step "Paste it into the v1be-agent entry's notes, BEGIN and END lines included."
warn "Never paste it into chat. Anyone with this key can act as the App."
step "Delete the .pem file from Downloads, and empty the Recycle Bin."
pause "Press Enter when the key is saved and the file is gone."

finish
say "Next, close this Sandbox. It holds your owner login."
say "Then, in a container terminal, run:"
say "  bash /workspaces/v1be/v1be-infra/.devcontainer/bot-identity.sh"
say "Tell Claude when its three checks pass."
note "Don't share the key."
}

run_wizard "$@"; exit
